// Paste this into an n8n Code node (Run Once for All Items mode)
// Drop it right after the Webhook node on the POST branch

const timestamp = new Date().toISOString();
const item = $input.first().json;

// Pull out the key parts of the Facebook payload
const entry = item?.body?.entry?.[0];
const messaging = entry?.messaging?.[0];

const report = {
  timestamp,

  // What type of event is this?
  event_type: (() => {
    if (messaging?.message?.text)       return "TEXT_MESSAGE";
    if (messaging?.message?.is_echo)    return "ECHO (your page sent this)";
    if (messaging?.delivery)            return "DELIVERY_CONFIRMATION";
    if (messaging?.read)                return "READ_RECEIPT";
    if (messaging?.postback)            return "POSTBACK_BUTTON";
    if (messaging?.referral)            return "REFERRAL";
    return "UNKNOWN - see raw_messaging below";
  })(),

  // Who sent it?
  sender_id:    messaging?.sender?.id    ?? "NOT FOUND",
  recipient_id: messaging?.recipient?.id ?? "NOT FOUND",

  // The actual message
  message_text: messaging?.message?.text ?? "NO TEXT",
  message_id:   messaging?.message?.mid  ?? "NO MESSAGE ID",

  // Is this a duplicate? Same mid = same message sent twice by Facebook
  mid_for_dedup: messaging?.message?.mid ?? null,

  // Raw dump in case something unexpected is coming in
  raw_messaging: messaging ?? null,
  raw_entry_id:  entry?.id ?? null,
  entry_time:    entry?.time ?? null,

  // Full item count (should always be 1 per execution)
  total_items: $input.all().length,
};

// This will show in the node's output so you can inspect it
console.log("=== WEBHOOK TRIGGER ===", JSON.stringify(report, null, 2));

return [{ json: report }];

const messageText = $input.first().json.body.entry[0].messaging[0].message.text;
const senderId = $input.first().json.body.entry[0].messaging[0].sender.id;

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessages) staticData.seenMessages = {};

const key = `${senderId}_${messageText}`;
const now = Date.now();

// Clean up entries older than 1 minute
for (const k of Object.keys(staticData.seenMessages)) {
  if (now - staticData.seenMessages[k] > 60000) {
    delete staticData.seenMessages[k];
  }
}

// If same sender sent same text within 1 minute, drop it
if (staticData.seenMessages[key]) {
  return [];
}

// Mark as seen and forward
staticData.seenMessages[key] = now;
return $input.all();

const item = $input.first().json;
const messaging = item.body.entry[0].messaging[0];
const message = messaging.message;

const isText = !!message.text;
const isAudio = message.attachments?.[0]?.type === "audio";

if (isText) {
  return $input.all();
}

if (isAudio) {
  const audioUrl = message.attachments[0].payload.url;

  // Download the audio file using n8n's built-in http
  const response = await this.helpers.httpRequest({
    method: "GET",
    url: audioUrl,
    encoding: "arraybuffer",
    returnFullResponse: true,
  });

  const audioBuffer = Buffer.from(response.body);

  // Convert to n8n binary directly
  const binaryData = await this.helpers.prepareBinaryData(
    audioBuffer,
    "audio.mp4",
    "audio/mp4"
  );

return [{
    json: {
      ...item,
      audioMimeType: "audio/mp4",
      audioUrl: audioUrl,
      isAudioMessage: true,
      senderId: messaging.sender.id,
    },
    binary: {
      data: binaryData
    }
  }];
}

return [];

const item = $input.first().json;

let messageText;
let senderId;

// If coming from audio path (Groq response has 'task' field)
if (item.task === 'transcribe') {
  messageText = item.text;
  senderId = $('Code in JavaScript1').first().json.body.entry[0].messaging[0].sender.id;
}
// If coming from text path
else {
  messageText = item.body.entry[0].messaging[0].message.text;
  senderId = item.body.entry[0].messaging[0].sender.id;
}

return [{
  json: {
    messageText,
    senderId
  }
}];
